import { escapeHtml, productionCss, tokenVariables, VisualCase } from '../test/visual';
import { authoringCases } from './authoring.visual-cases';
import { historyCases } from './history.visual-cases';
import { printerCases } from './printer.visual-cases';
import { runtimeCases } from './runtime.visual-cases';
import { setupCases } from './setup.visual-cases';

const cases: VisualCase[] = [...runtimeCases, ...authoringCases, ...historyCases, ...printerCases, ...setupCases];

const DOCK_WIDTHS = [429, 320] as const;
// The thread insets its items 16 on each side.
const THREAD_INSET = 32;

describe('Agent UI state matrices', () => {
  it('names every state once', () => {
    expect(new Set(cases.map((item) => item.id)).size).toBe(cases.length);
  });

  it.each(cases)('renders $matrix · $name from its state inputs', async (entry) => {
    const html = await entry.build();
    for (const expected of entry.expects) expect(html).toContain(expected);
    expect(html).not.toContain('undefined');
    expect(html).not.toContain('NaN');
  });

  it('writes a review page using the production components and stylesheet', async () => {
    const out = process.env.PREVIEW_OUT;
    if (!out) return;

    const { light, dark } = tokenVariables();
    const built = new Map<string, string>();
    for (const entry of cases) built.set(entry.id, await entry.build());

    const matrices = [...new Set(cases.map((item) => item.matrix))];
    const slug = (name: string) => name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const figure = (entry: VisualCase, mode: string, dock: number) => {
      const width = entry.frame === 'card' ? dock - THREAD_INSET : dock;
      const inner = entry.frame === 'pane'
        ? `<div class="stage ${mode}" style="width:${width}px">${built.get(entry.id)}</div>`
        : `<div class="${entry.frame === 'block' ? 'block' : 'specimen'} ${mode} ${entry.within ?? ''}" style="width:${width}px">${built.get(entry.id)}</div>`;
      return `<figure data-case="${entry.id}" data-mode="${mode}" data-dock="${dock}">
  <figcaption>${escapeHtml(entry.name)}</figcaption>${inner}</figure>`;
    };
    const sections = matrices.map((matrix) => {
      const members = cases.filter((item) => item.matrix === matrix);
      const groups = (['light', 'dark'] as const).flatMap((mode) => DOCK_WIDTHS.map((dock) =>
        `<h3 id="${slug(matrix)}-${mode}-${dock}">${mode} · ${dock} DIP dock</h3>
<div class="grid">${members.map((entry) => figure(entry, mode, dock)).join('\n')}</div>`)).join('\n');
      return `<section id="${slug(matrix)}"><h2>${escapeHtml(matrix)} · Figma ${members[0].node}</h2>${groups}</section>`;
    }).join('\n');
    const nav = matrices.map((matrix) => `<a href="#${slug(matrix)}">${escapeHtml(matrix)}</a>`).join('');

    // The focus a case left is a mark, not real focus, so the stylesheet's
    // own focus rules are pointed at the mark: a control draws focus as it
    // does in the app, a ring where it has one and none where it has not.
    writeFileSync(out, `<!doctype html><html lang="en"><meta charset="utf-8">
<title>Agent UI state matrices</title>
<style>
:root { ${light} }
${productionCss().replaceAll(':focus-visible', '[data-visual-focus]')}
.dark { ${dark} }
html, body { height: auto; }
body { margin:0; padding:16px; background:var(--surface-subtle); color:var(--text-primary); font:var(--font-body); }
nav { display:flex; flex-wrap:wrap; gap:12px; margin-bottom:20px; font:var(--font-label); }
nav a { color:var(--action-primary); }
h1 { font:var(--font-section); margin:0 0 12px; }
h2 { font:var(--font-body-bold); margin:32px 0 4px; }
h3 { font:var(--font-label-bold); margin:16px 0 8px; color:var(--text-secondary); }
// The Agent page in its Preferences mode (?panel=preferences): JusPrin's
// Preferences window. It speaks the same bridge as the Agent panel, so the
// key checks and AI tool connections it offers are the ones Agent setup
// runs, and adds one message of its own, preferences_action.

import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { Preferences, PreferencesActions } from './components/Preferences';

export function PreferencesApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  const actions = useMemo<PreferencesActions>(
    () => ({
      set: (name, value) => client.send('preferences_action', { action: 'set', name, value }),
      run: (action, details) => client.send('preferences_action', { ...details, action }),
      checkKey: (provider, apiKey) => client.send('setup_check_key', { provider, apiKey }),
      cancelCheck: () => client.send('setup_cancel', {}),
      removeKey: (provider) => client.send('setup_remove_key', { provider }),
      refreshTools: () => client.send('mcp_catalog', {}),
      previewTool: (toolId) => client.send('mcp_preview', { toolId }),
      connectTool: (toolId) => client.send('mcp_connect', { toolId }),
      revealTool: (toolId) => client.send('reveal_path', { toolId }),
    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title="Preferences could not reach JusPrin" detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.preferences) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--preferences">
      <Preferences
        preferences={state.preferences}
        setup={state.setup}
        savedKeys={state.savedKeys}
        mcpCatalog={state.mcpCatalog}
        mcpPreview={state.mcpPreview}
        mcpStatus={state.mcpStatus}
        actions={actions}
      />
    </div>
  );
}

