// refused that key in this session. Sent after the handshake and whenever one
// of them changes. saved_keys capability.
inline constexpr const char* kSetupKeys          = "setup_keys";
inline constexpr const char* kMcpStatus          = "mcp_status";
// One new change log entry; the full list travels in `state`.
inline constexpr const char* kChangeAdded        = "change_added";
// Work the application runs outside the chat: started, moved on, or ended.
inline constexpr const char* kWorkUpdated        = "work_updated";
// Asks the page to open its own setup flow, as its "Set up the agent" button
// does; sent when another JusPrin surface sends the person there.
// Each configured provider's models, sent after the handshake and again as
// each list arrives: {defaultProvider, providers: [{id, label, state, models:
// [{id, label, efforts, defaultEffort}]}]}. model_choice capability.
inline constexpr const char* kModelCatalog       = "model_catalog";
// The active chat's choice after a set_chat_model: {conversationId, chatModel}.
inline constexpr const char* kChatModel          = "chat_model";

namespace Slic3r::GUI::JusPrin {

// Which of the page's surfaces this view is. The page reads it from the query
// string it is loaded with (see main.tsx):
//   Conversation   the docked panel: header, chat list, thread, composer;
//   EmbeddedSetup  a throwaway setup-only instance, the setup screens alone;
//   PrinterPanel   Home's printer conversation: the printer session's own
//                  header, pinned card and chips around the same thread;
//   Preferences    JusPrin's Preferences window, which draws the Agent's
//                  connection rows the setup screens draw.
enum class AgentPageMode { Conversation, EmbeddedSetup, PrinterPanel, Preferences };

class AgentWebView : public wxPanel
{
public:
    AgentWebView(wxWindow*                        parent,
                 const ShellTheme&                theme,
                 Workspace::IWorkspace&           workspace,
                 Agent::ProjectPersistence&       persistence,
                 Agent::AgentAvailability         availability,
                 Agent::AgentServicePtr            agent = {},
                 Agent::AgentSetupServicePtr       setup = {},
                 AgentPageMode                     mode = AgentPageMode::Conversation);
    ~AgentWebView() override;

    void apply_appearance(bool dark);
    void reload();
    // When the shell temporarily gives this view the whole workspace, keep
    // its native error surface navigable even if the web bridge never loads.
    void set_error_fallback_actions(const wxString& return_label,
                                    const wxString& manual_label,
                                    std::function<void()> on_return,
                                    std::function<void()> on_manual);

    Agent::AgentHost&    host() { return *m_host; }
wxString agent_page_url(AgentPageMode mode)
{
    wxString url;
    if (const char* dev = std::getenv("JUSPRIN_AGENT_DEV_URL"); dev != nullptr && *dev != '\0') {
        url = wxString::FromUTF8(dev);
    } else {
        const boost::filesystem::path page = agent_page_path();
        if (!boost::filesystem::exists(page))
            return {};
        url = wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
    }
    if (mode == AgentPageMode::EmbeddedSetup)
        url += "?embedded=1";
    else if (mode == AgentPageMode::PrinterPanel)
        url += "?panel=printer";
    else if (mode == AgentPageMode::Preferences)
        url += "?panel=preferences";
    return url;
}

} // namespace

AgentWebView::AgentWebView(wxWindow*                  parent,

