  render(<App getTransport={() => host.transport} />);
  connect(host, emptyState({ agent: { status: 'unavailable' }, conversation: [
    { id: 'n-1', role: 'note', state: 'complete', text: '', attempt: 1, fileReport, fileReportCard: true },
  ] }));
