if (self->persistence().draft() != "offer|header|no-chrome|setup-live|ask-inert") {
    std::cerr << "HARNESS DETAIL dock state was " << self->persistence().draft() << '\n';
    const auto& document = self->persistence().document();
    const std::string active = document.active_conversation_id();
    for (const auto& change : document.changes())
        std::cerr << "HARNESS PROBE change kind=" << change.kind << " actor=" << change.actor
                  << " label='" << change.label << "' conv=" << change.conversation_id
                  << (change.conversation_id == active ? " (active)" : "") << '\n';
    for (const auto& work : document.work())
        std::cerr << "HARNESS PROBE work kind=" << work.kind << " title='" << work.title
                  << "' state=" << work.state << " conv=" << work.conversation_id << '\n';
    for (const auto& message : document.messages(active))
        std::cerr << "HARNESS PROBE message role=" << int(message.role) << '\n';
